// Use the native Perfected Strike calculation while retaining the printed Damage variable.
internal sealed class KnowledgeDamageVar : CalculatedDamageVar
{
    private readonly Func<CardModel, int> _count;

    internal KnowledgeDamageVar(Func<CardModel, int> count) : base(ValueProp.Move)
    {
        _count = count;
        WithMultiplier((card, _) => count(card));
    }

    protected override DynamicVar GetBaseVar() => ((CardModel)_owner!).DynamicVars.Damage;

    public override void UpdateCardPreview(CardModel card, CardPreviewMode previewMode, Creature? target, bool runGlobalHooks)
    {
        if (card.CombatState == null && card.IsMutable && card.Owner != null)
        {
            var damage = new DamageVar(card.DynamicVars.Damage.BaseValue + _count(card) * GetExtraVar().BaseValue, Props);
            damage.UpdateCardPreview(card, previewMode, target, runGlobalHooks);
            PreviewValue = damage.PreviewValue;
        }
        else base.UpdateCardPreview(card, previewMode, target, runGlobalHooks);
        card.DynamicVars.Damage.PreviewValue = PreviewValue;
    }
}

internal sealed class KnowledgeBlockVar() : CalculatedBlockVar(ValueProp.Move)
{
    protected override DynamicVar GetBaseVar() => ((CardModel)_owner!).DynamicVars.Block;
    protected override DynamicVar GetExtraVar() => ((CardModel)_owner!).DynamicVars["N1"];

    public override void UpdateCardPreview(CardModel card, CardPreviewMode previewMode, Creature? target, bool runGlobalHooks)
    {
        if (card.CombatState == null && card.IsMutable && card.Owner != null)
        {
            var block = new BlockVar(card.DynamicVars.Block.BaseValue +
                CatalogCard.CountDeckKnowledge(card) * card.DynamicVars["N1"].BaseValue, Props);
            block.UpdateCardPreview(card, previewMode, target, runGlobalHooks);
            PreviewValue = block.PreviewValue;
        }
        else base.UpdateCardPreview(card, previewMode, target, runGlobalHooks);
        card.DynamicVars.Block.PreviewValue = PreviewValue;
    }
}

src/Models/KnowledgeGroup.cs:
namespace ShoujoKagekiJunna.Models;

public sealed record KnowledgeGroup(string MainCardId, string[] GrantedCardIds,
    Dictionary<string, int> GrantedCardCounts, int MainCardCount = 1)
{
    public IEnumerable<(string Id, int Count)> Members => GrantedCardIds.Prepend(MainCardId)
        .Select(id => (id, id == MainCardId ? MainCardCount : GrantedCardCounts.GetValueOrDefault(id, 1)));

    public static KnowledgeGroup[] Initialize(IEnumerable<KnowledgeGroup> definitions)
    {
        var originals = definitions.ToArray();
        var groups = originals.ToDictionary(group => group.MainCardId);
        var references = originals.SelectMany(group => group.GrantedCardIds
            .Where(id => group.GrantedCardCounts.GetValueOrDefault(id, 1) > 0).Distinct()
            .Select(id => (Id: id, Group: group))).GroupBy(link => link.Id);
        foreach (var reference in references)
        {
            if (groups.ContainsKey(reference.Key)) continue;
            var sources = reference.Select(link => link.Group).ToArray();
            var counts = sources.Length == 1
                ? sources[0].Members.ToDictionary(member => member.Id, member => member.Count)
                : sources.ToDictionary(source => source.MainCardId, _ => 1);
            counts.Remove(reference.Key, out int ownCount);
            groups.Add(reference.Key, new(reference.Key, counts.Keys.ToArray(), counts,
                ownCount > 0 ? ownCount : 1));
        }
        return groups.Values.ToArray();
    }
}

src/Models/KnowledgeRelation.cs:
namespace ShoujoKagekiJunna.Models;

/// <summary>One source model's run-wide direct associations and quantities.</summary>
public sealed record KnowledgeRelation(string EntranceId, Dictionary<string, int> CardCounts)
{
    public IEnumerable<(string Id, int Count)> Members => CardCounts.OrderBy(pair => pair.Key != EntranceId)
        .Select(pair => (pair.Key, pair.Value));

    public static KnowledgeRelation Merge(List<KnowledgeRelation> groups, KnowledgeRelation incoming, string preferredEntrance)
    {
        var counts = new Dictionary<string, int>(incoming.CardCounts);
        foreach (var group in groups.Where(group => group.EntranceId == incoming.EntranceId).ToArray())
        {
            foreach (var (id, count) in group.CardCounts)
                counts[id] = Math.Max(counts.GetValueOrDefault(id), count);
            groups.Remove(group);
        }
        var merged = new KnowledgeRelation(incoming.EntranceId, counts);
        groups.Add(merged);
        return merged;
    }
}

